   pairs=[['Precondition','Both child subtrees are already heaps'],['Smaller child','The candidate promoted during a downward repair'],['Leaf','No child exists for a downward swap']];
   steps=['Assume both child subtrees are valid heaps','Choose the smaller existing child','Swap if the current key is larger','Repeat at the moved key until ordered or a leaf'];
