export function extraTopic(lecture){const row=extraPlans[lecture-40];if(!row)throw Error('Unreviewed advanced DS topic '+lecture);const [label,...rest]=row,titles=rest.slice(0,3),kind=rest[3],spec=specs[kind];return {label,titles,kind,lab:kind,...spec,questions:questions(kind,3+lecture%6)};}
